import{_ as o,a0 as p,w as d,s as r,I as t,x as i,a1 as e,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"10 個在 Linux 終端中生成有趣的 ASCII 字符畫的工具 | LCTT x X-CMD","titleTemplate":false,"description":"10 個在 Linux 終端中生成有趣的 ASCII 字符畫的工具 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 個在 Linux 終端中生成有趣的 ASCII 字符畫的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 個在 Linux 終端中生成有趣的 ASCII 字符畫的工具 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20220706 10 Tools to Generate and Have Fun With ASCII Art in Linux Terminal","title":"10 個在 Linux 終端中生成有趣的 ASCII 字符畫的工具","tag":"202309","desc":""},"relativePath":"202309/20220706 10 Tools to Generate and Have Fun With ASCII Art in Linux Terminal.md","filePath":"[post].md"}'),h={name:"202309/20220706 10 Tools to Generate and Have Fun With ASCII Art in Linux Terminal.md"};function u(g,s,c,k,b,f){const a=p("Link");return d(),r("div",null,[s[33]||(s[33]=t("h1",{id:"_10-個在-linux-終端中生成有趣的-ascii-字符畫的工具",tabindex:"-1"},[i("10 個在 Linux 終端中生成有趣的 ASCII 字符畫的工具 "),t("a",{class:"header-anchor",href:"#_10-個在-linux-終端中生成有趣的-ascii-字符畫的工具","aria-label":"Permalink to “10 個在 Linux 終端中生成有趣的 ASCII 字符畫的工具”"},"​")],-1)),s[34]||(s[34]=t("blockquote",null,[t("p",null,"以為 Linux 終端都是嚴肅的工作？想多了。以下是你可以在終端中使用 ASCII 字符畫做的幾件趣事。")],-1)),t("p",null,[s[1]||(s[1]=i("Linux 終端其實沒有想像中的那樣 ",-1)),e(a,{href:"https://itsfoss.com/basic-terminal-tips-ubuntu/"},{default:l(()=>[...s[0]||(s[0]=[i("可怕",-1)])]),_:1}),s[2]||(s[2]=i("。",-1))]),t("p",null,[s[4]||(s[4]=i("當然啦，一開始它可能會令人望而卻步，但是當我們更 ",-1)),e(a,{href:"https://itsfoss.com/love-thy-terminal/"},{default:l(()=>[...s[3]||(s[3]=[i("瞭解",-1)])]),_:1}),s[5]||(s[5]=i(" 它的時候，我們就會喜歡上它的。",-1))]),s[35]||(s[35]=n('<p>你可能會使用終端來做一些嚴肅的工作。不過，你也可以在終端中做很多有趣的事情。</p><p>其中的一項就是試一試<ruby>ASCII 字符畫<rt>ASCII art</rt></ruby>。你可以在 Linux 終端中用各種命令列工具以 ASCII 的形式顯示一些預定義的或是隨機的消息、玩遊戲，抑或是播放動畫。</p><p>我的同事 Sreenath 喜歡探索此類不尋常的命令列工具並將他的發現分享給我。現在，我也將他的發現與你分享。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/ascii-art-tools-linux.png" alt="ascii art tools linux"></p><p>你的 Linux 發行版的倉庫中應該已經有這些程序中的大多數了。你可以用系統的包管理器安裝它們。為了使文章簡潔，下文的安裝指南均以 Ubuntu 為例。</p><h3 id="_1、lolcat-向終端加入繽紛色彩" tabindex="-1">1、lolcat：向終端加入繽紛色彩 <a class="header-anchor" href="#_1、lolcat-向終端加入繽紛色彩" aria-label="Permalink to “1、lolcat：向終端加入繽紛色彩”">​</a></h3><p>雖然 <code>lolcat</code> 與 ASCII 字符畫沒有任何關係，至少，沒有直接關係。</p><p>但是，我還是在文章開頭就列出了它，因為它可以與其他的 ASCII 工具組合使用。</p><p>所以，它能做什麼呢？它與 <code>cat</code> 指令很相似，但是它向輸出內容加入隨機的漸變色彩。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/lolcat.png" alt="lolcat"></p><p>目前它看起來可能沒什麼用，但當其他 ASCII 工具通過 <code>lolcat</code> 輸出時，你會看到它的效果。</p><p>用 <code>apt</code> 安裝 <code>lolcat</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lolcat</span></span></code></pre></div><h3 id="_2、aewan-漂亮地顯示-ascii-字符" tabindex="-1">2、Aewan：漂亮地顯示 ASCII 字符 <a class="header-anchor" href="#_2、aewan-漂亮地顯示-ascii-字符" aria-label="Permalink to “2、Aewan：漂亮地顯示 ASCII 字符”">​</a></h3><p>Aewan 是一個多層 ASCII 圖形、動畫編輯器。它可以生成獨立的，可被 <code>cat</code> 命令查看的 ASCII 字符畫文件和便於命令列工具集成與解析的格式。</p><p>它包括兩個工具：ASCII 編輯器 <code>aewan</code>，和文件查看器 <code>aecat</code>。</p><p>這裏不討論編輯器部分。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/Aewan-initial-layout.png" alt="aewan 的初始狀態佈局"></p><p>用 <code>aecat</code> 命令以 ASCII 格式漂亮地顯示任何文本。注意下面的截屏中字母的使用方式。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/aewan-output.png" alt="aewan output"></p><p>用下面的命令安裝 <code>aewan</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install aewan</span></span></code></pre></div><p>然後這樣使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>aecat hello</span></span></code></pre></div><h3 id="_3、cowsay-讓-ascii-牛複述你想説的話" tabindex="-1">3、Cowsay：讓 ASCII 牛複述你想説的話 <a class="header-anchor" href="#_3、cowsay-讓-ascii-牛複述你想説的話" aria-label="Permalink to “3、Cowsay：讓 ASCII 牛複述你想説的話”">​</a></h3><p>這頭牛在説什麼？你想什麼就讓它説什麼。</p><p><code>cowsay</code> 是經驗豐富的 Linux 用户中流行的工具。它顯示了一個 ASCII 格式的牛，會重複你提供的文本。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/cowsay-1.png" alt="cowsay"></p><p>但不僅限於牛。你也可以將其更改為其他的角色。比如，一條龍（火龍君臨）：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/cowsay.png" alt="cowsay"></p><p>你注意到截圖中的色彩了嗎？這正是上文提到過的 <code>lolcat</code> 命令的魔力所在。</p><p>用下列命令安裝 <code>cowsay</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install cowsay</span></span></code></pre></div><p>裝好之後，這樣使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cowsay hello</span></span></code></pre></div>',35)),t("p",null,[s[7]||(s[7]=i("你可以參考它的 ",-1)),e(a,{href:"https://itsfoss.com/linux-man-page-guide/"},{default:l(()=>[...s[6]||(s[6]=[i("手冊",-1)])]),_:1}),s[8]||(s[8]=i("，瀏覽其他配置和選項。",-1))]),s[36]||(s[36]=n('<h3 id="_4、jp2a-圖片轉-ascii-字符畫" tabindex="-1">4、jp2a：圖片轉 ASCII 字符畫 <a class="header-anchor" href="#_4、jp2a-圖片轉-ascii-字符畫" aria-label="Permalink to “4、jp2a：圖片轉 ASCII 字符畫”">​</a></h3><p><code>jp2a</code> 是一個在 Linux 終端中將圖像轉換為 ASCII 字符畫的命令列工具。它適用於 JPEG 和 PNG 文件，允許彩色輸出和用你選定的字符顯示 ASCII 字符畫。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/jp2a.png" alt="jp2a"></p><p>用下列命令安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install jp2a</span></span></code></pre></div><p>你可以像這樣得到彩色的輸出，並且保存到文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>jp2a --output=ascii.txt --colors input.png</span></span></code></pre></div><p>它並不是這類工具中的唯一一種，比如，<code>ascii-image-converter</code> 和幾個其他的工具也可以達成相同的效果。在這裏不再一一討論了。</p><h3 id="_5、linuxlogo-用-ascii-格式顯示-linux-發行版的徽標" tabindex="-1">5、linuxlogo：用 ASCII 格式顯示 Linux 發行版的徽標 <a class="header-anchor" href="#_5、linuxlogo-用-ascii-格式顯示-linux-發行版的徽標" aria-label="Permalink to “5、linuxlogo：用 ASCII 格式顯示 Linux 發行版的徽標”">​</a></h3>',9)),t("p",null,[s[10]||(s[10]=i("正如起名，它 ",-1)),e(a,{href:"https://itsfoss.com/display-linux-logo-in-ascii/"},{default:l(()=>[...s[9]||(s[9]=[i("用 ASCII 格式顯示 Linux 發行版的標誌",-1)])]),_:1}),s[11]||(s[11]=i("。",-1))]),t("p",null,[s[13]||(s[13]=i("不，不是我們 ",-1)),e(a,{href:"https://itsfoss.com/tux-trivia/"},{default:l(()=>[...s[12]||(s[12]=[i("喜愛的 Linux 標誌 Tux",-1)])]),_:1}),s[14]||(s[14]=i("，而是你的 Linux 發行版的徽標。它還顯示一些其他信息，比如 Linux 內核版本、CPU、RAM、主機名等等。",-1))]),s[37]||(s[37]=n('<p><img src="https://itsfoss.com/content/images/wordpress/2022/07/linux-logo.png" alt="linux logo"></p><p>用 <code>apt</code> 安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install linuxlogo</span></span></code></pre></div><p>輸入 <code>linuxlogo</code> 就可以用啦。</p><h3 id="_6、neoftech-顯示-linux-標誌和系統信息" tabindex="-1">6、Neoftech：顯示 Linux 標誌和系統信息 <a class="header-anchor" href="#_6、neoftech-顯示-linux-標誌和系統信息" aria-label="Permalink to “6、Neoftech：顯示 Linux 標誌和系統信息”">​</a></h3><p>上面的 Linux 標誌有點太簡化了。你可以用 Neofetch 放大它。</p><p>它以更漂亮的方式顯示發行版以及一些系統信息，如內核、運行時間、桌面環境、主題和圖標等等。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/neofetch.png" alt="neofetch"></p><p>你還可以通過 <code>lolcat</code> 解析它，獲得彩虹色的輸出。</p><p>用這行命令安裝 Neofetch：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install neofetch</span></span></code></pre></div><p>然後，輸入 <code>neofetch</code> 就可以運行啦。</p><p>還有一個與 Neofetch 很像的工具，<code>screenfetch</code>。用哪個都行。</p><h3 id="_7、fortune-看看命運如何" tabindex="-1">7、fortune：看看命運如何 <a class="header-anchor" href="#_7、fortune-看看命運如何" aria-label="Permalink to “7、fortune：看看命運如何”">​</a></h3><p>開玩笑啦。這樣的事情根本就不存在。</p><p>不過，幸運餅乾仍然很流行，所以顯然，人們喜歡閲讀隨機的預測或説法。</p><p>你可以在 Linux 終端中用 Fortune 命令達到類似效果：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/fortune-cookie-Linux.png" alt="fortune cookie linux"></p><p>你可以用下面的命令安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fortune</span></span></code></pre></div><p>裝好之後，在終端中輸入 <code>fortune</code> 來得到一條隨機消息。</p><h3 id="_8、pv-讓一切動起來" tabindex="-1">8、pv：讓一切動起來 <a class="header-anchor" href="#_8、pv-讓一切動起來" aria-label="Permalink to “8、pv：讓一切動起來”">​</a></h3><p>這是非預期使用 Linux 命令的典型例子。<code>pv</code> 命令本來用於通過管道監控數據的進度。</p><p>但你可以使用它來對顯示任何命令的輸出加入動畫效果。將其與上述的命令結合起來，你就可以看到 ASCII 字符畫逐漸顯現在屏幕上，就像正在輸入一樣。</p><p>不太明白？看看這個：</p><p><img src="https://player.vimeo.com/video/727286686" alt="A Video from YouTube"></p><p>用下面的命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install pv</span></span></code></pre></div><p>然後按這樣使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>neofetch | pv -qL 200 | lolcat</span></span></code></pre></div><p>數字越大，速度越快。</p><h3 id="_9、cmatrix-類似黑客帝國的-ascii-動畫" tabindex="-1">9、cmatrix：類似黑客帝國的 ASCII 動畫 <a class="header-anchor" href="#_9、cmatrix-類似黑客帝國的-ascii-動畫" aria-label="Permalink to “9、cmatrix：類似黑客帝國的 ASCII 動畫”">​</a></h3><p>還記得 “黑客帝國” 嗎？下落的綠色代碼是黑客帝國和黑客的象徵。</p><p>你可以使用 <code>cmatrix</code> 命令在 Linux 終端用 ASCII 模擬運行下落代碼。</p><p>我在這裏用一張圖片代替視頻。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/cmatrix.png" alt="cmatrix"></p><p>你可以用 <code>apt</code> 安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install cmatrix</span></span></code></pre></div><p>安裝好之後，用它運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cmatrix</span></span></code></pre></div><p>它會立即啓動，並不斷生成隨機的綠色文本，帶着從屏幕上落下後消失的動畫效果。該命令會持續運行。使用 <code>Ctrl+C</code> 停止運行程序。</p><h3 id="_10、cbonsai-在你的終端種植盆景" tabindex="-1">10、cbonsai：在你的終端種植盆景 <a class="header-anchor" href="#_10、cbonsai-在你的終端種植盆景" aria-label="Permalink to “10、cbonsai：在你的終端種植盆景”">​</a></h3><p>有沒有園藝的天賦？在終端中種植一棵 ASCII 盆景樹怎麼樣？</p><p><code>cbonsai</code> 是一個可讓你以 ASCII 格式運行盆景樹生長動畫的有趣 Linux 命令。</p><p>幾天前我發了一條關於 <code>cbonsai</code> 命令的 YouTube 短視頻。</p><p><img src="https://youtu.be/KqhqgdezPp8" alt="Have fun with the Linux terminal 😍 🐧"></p><p>你可以用下面的命令安裝 <code>cbonsai</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install cbonsai</span></span></code></pre></div><p>用這行命令運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cbonsai -l</span></span></code></pre></div><h3 id="試試更多" tabindex="-1">試試更多 <a class="header-anchor" href="#試試更多" aria-label="Permalink to “試試更多”">​</a></h3>',51)),t("p",null,[s[16]||(s[16]=i("還有很多這樣的有趣的命令列工具，甚至還有 ",-1)),e(a,{href:"https://itsfoss.com/best-ascii-games/"},{default:l(()=>[...s[15]||(s[15]=[i("ASCII 遊戲",-1)])]),_:1}),s[17]||(s[17]=i("。有時，看着它們給周圍的人帶來歡樂真的很有趣。",-1))]),s[38]||(s[38]=t("p",null,[i("這些命令能派上用場嗎？我不確定是否可用，但你可以在 "),t("code",null,".bashrc"),i(" 文件中添加其中一些，這樣一旦打開終端會話，命令就會立即運行。")],-1)),s[39]||(s[39]=t("p",null,[i("許多系統管理員在共享的 Linux 系統上都會這樣做。像 "),t("code",null,"cowsay"),i(" 或 "),t("code",null,"figlet"),i(" 這樣的程序可以用來以漂亮的方式顯示消息或系統概況。")],-1)),s[40]||(s[40]=t("p",null,"你也可以在你的 Bash 腳本中使用其中的一些程序，尤其是當你需要突出顯示某些內容時。",-1)),s[41]||(s[41]=t("p",null,"ASCII 字符畫在 Linux 中可能還會有其他用途。你可以與我們分享。",-1)),s[42]||(s[42]=t("hr",null,null,-1)),t("p",null,[s[19]||(s[19]=i("via: ",-1)),e(a,{href:"https://itsfoss.com/ascii-art-linux-terminal/"},{default:l(()=>[...s[18]||(s[18]=[i("https://itsfoss.com/ascii-art-linux-terminal/",-1)])]),_:1})]),t("p",null,[s[24]||(s[24]=i("作者：",-1)),e(a,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...s[20]||(s[20]=[i("Abhishek Prakash",-1)])]),_:1}),s[25]||(s[25]=i(" 選題：",-1)),e(a,{href:"https://github.com/lkxed"},{default:l(()=>[...s[21]||(s[21]=[i("lkxed",-1)])]),_:1}),s[26]||(s[26]=i(" 譯者：",-1)),e(a,{href:"https://github.com/CoWave-Fall"},{default:l(()=>[...s[22]||(s[22]=[i("泠知落汐",-1)])]),_:1}),s[27]||(s[27]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[23]||(s[23]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[30]||(s[30]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[28]||(s[28]=[i("LCTT",-1)])]),_:1}),s[31]||(s[31]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...s[29]||(s[29]=[i("Linux中國",-1)])]),_:1}),s[32]||(s[32]=i(" 榮譽推出",-1))])])}const I=o(h,[["render",u]]);export{C as __pageData,I as default};
